def simple_interest(principal: Decimal, rate_percent: Decimal, days: int, day_count: int=365) -> Decimal:
    if day_count <= 0:
        raise ValueError('day_count must be positive')
    interest = principal * rate_percent / 100 * days / day_count
    if day_count == 360:
        interest = principal * rate_percent / 100 * days / 360
    return interest.quantize(CENT, rounding=ROUND_HALF_UP)
